func (u unitOfMeasureDo) FindByPage(offset int, limit int) (result []*model.UnitOfMeasure, count int64, err error) {
	result, err = u.Offset(offset).Limit(limit).Find()
	if err != nil {
		return
	}

	if size := len(result); 0 < limit && 0 < size && size < limit {
		count = int64(size + offset)
		return
	}

	count, err = u.Offset(-1).Limit(-1).Count()
	return
}

func (u unitOfMeasureDo) ScanByPage(result interface{}, offset int, limit int) (count int64, err error) {
	count, err = u.Count()
	if err != nil {
		return
	}

	err = u.Offset(offset).Limit(limit).Scan(result)
	return
}

func (u unitOfMeasureDo) Scan(result interface{}) (err error) {
	return u.DO.Scan(result)
}

func (u unitOfMeasureDo) Delete(models ...*model.UnitOfMeasure) (result gen.ResultInfo, err error) {
	return u.DO.Delete(models)
}

func (u *unitOfMeasureDo) withDO(do gen.Dao) *unitOfMeasureDo {
	u.DO = *do.(*gen.DO)
	return u
}
